fetch('/big-file', { signal: controller.signal })
  .then(r => r.text())
  .catch(e => {
    if (e.name === 'AbortError') console.log('用户取消了');
  });

setTimeout(() => controller.abort(), 1000);  // 1 秒后取消
```

