```javascript
// 可选链 ?.
user?.address?.city;
fn?.();
arr?.[0];

// 空值合并 ??（只在 null/undefined 时用右边）
const port = config.port ?? 3000;
0 ?? 9;        // 0（不是 9，比 || 更精确）

