let ar = [5, 12, 6, 3, 9, 2, 1, 7];

function getthreenum(arr, target, result = []) {
arr = arr.sort((a, b) => a - b)
const len = arr.length;
for (let i = 0; i < len; i++) {
let j = i + 1;
let k = len - 1;
while (j < k) {
if (arr[j] + arr[k] > target - arr[i]) {
k--;
} else if (arr[j] + arr[k] < target - arr[i]) {
j++;
