var combine = function (n, k) {
  let result = [];
  function find(collection, from) {
    if (collection.length === k) {
      result.push(collection);
      return;
    }
    for (let i = from; i <= n; i++) {
      find(collection.concat(i), i + 1);
    }
  }
  find([], 1);
  return result;
};
