41. First Missing Positive

```python
class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)
        for i in range(n):
            # 注意这里是while
            while nums[i] >= 0 and nums[i] < n and nums[nums[i] - 1] != nums[i]:
                nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

        for i in range(n):
            if nums[i] != i + 1:
                return i + 1
        return n + 1
```

```python
class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        maxpos = 0
        for num in nums:
            if num > maxpos:
                maxpos = num
        minpos = maxpos
        for num in nums:
            if num < minpos and num > 0:
                minpos = num

        if minpos > 1:
            return 1
        for i in range(minpos + 1,maxpos + 1):
            if i in nums:
                continue
            else:
                return i
        return maxpos + 1
```

