```python
# 两障碍物之间的区间, 加到前后. 注意题目条件: nums元素的取值范围为[lower，upper]

class Solution:
    def findMissingRanges(self, nums, lower, upper):
        nums = [lower - 1] + nums + [upper + 1]
        res = []
        for i in range(1, len(nums)):
            if nums[i] - nums[i-1] > 1:
                l = nums[i-1] + 1
                h = nums[i] - 1
                res.append(str(l) if l == h else '{}->{}'.format(l, h))
        return res
```

