class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if len(s) == 0 or k > len(s):
            return 0
        c = Counter(s)

        for i, letter in enumerate(s):
            if c[letter] < k:
                sub1 = self.longestSubstring(s[:i], k)
                sub2 = self.longestSubstring(s[i+1:], k)
                break
        else:
            return len(s)
        return max(sub1, sub2)
```

```python
class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if len(s) < k:
            return 0
        # 找个字符串个数最少的字符
        t = min(set(s), key=s.count)
        # 最少字符的个数都大于等于k
        if s.count(t) >= k:
            return len(s)
        return max(self.longestSubstring(a, k) for a in s.split(t))
```

- 前缀和

```python
class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        from collections import Counter
        c = Counter()
        n = len(s)
        prefix = [c.copy()]
        for i in range(n):
            c[s[i]] += 1
            prefix.append(c.copy())

        def check(tmp):
            for val in tmp.values():
                if val < k:
                    return False
            return True

        res = 0
        for i in range(n + 1):
            for j in range(i):
                if check(prefix[i] - prefix[j]):
                    res = max(res, i - j)
                    break
        return res
```

# 76. Minimum Window Substring

`https://leetcode.com/problems/minimum-window-substring/`

## solution

```python
class Solution:
    def minWindow(self, s: str, t: str) -> str:
        t_counter = collections.Counter(t)
        s_counter = collections.defaultdict(int)

        l = 0
        valid_length = 0  # 记录窗口内和target对比的有效长度
        res = float('inf')
        res_start = -1

        for r, char in enumerate(s):
            s_counter[char] += 1
            if s_counter[char] <= t_counter[char]:
                valid_length += 1

            while valid_length == len(t):
                if r - l + 1 < res:
                    res = r - l + 1
                    res_start = l

                if s_counter[s[l]] <= t_counter[s[l]]:
                    valid_length -= 1

                s_counter[s[l]] -= 1
                l += 1

        return "" if res_start < 0 else s[res_start: res_start + res]
```

时间复杂度：O(m+n) <br>
空间复杂度：O(c)

```python
# https://zhuanlan.zhihu.com/p/143087981

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not s or not t or len(s)<len(t): # 排除特殊情况
            return ''

        s_count = collections.Counter()
        t_count = collections.Counter(t)
        l = 0
        res = ""
        for r in range(len(s)):
            s_count[s[r]] += 1

            while s_count & t_count == t_count:
                if r - l + 1 < len(res) or res == "":
                    res = s[l: r+1]
                s_count[s[l]] -= 1
                l += 1
        return res
```

