class Solution:
    def findAnagrams(self, s: str, p: str) -> List[int]:
        if len(s) < len(p):
            return []

        p_count = {}
        for char in p:
            p_count[char] = p_count.get(char, 0) + 1

        count = {}
        for char in s[:len(p)]:
            count[char] = count.get(char, 0) + 1

        res = []
        if count == p_count:
            res.append(0)
        for index in range(len(p), len(s)):
            r = s[index]
            l = s[index - len(p)]
            count[r] = count.get(r, 0) + 1
            count[l] -= 1

            if count[l] == 0:
                del count[l]

            if count == p_count:
                res.append(index - len(p) + 1)
        return res
```

